INSERT INTO tbl_categorias (id_categoria, codigo_categoria, nombre_categoria, descripcion, estado) VALUES
  (1, 'VALVULAS-Y-PORTAVALVULAS', 'Válvulas y Portaválvulas', 'Válvulas de bola, compresión, tipo enlace, cajas portaválvulas y accesorios de maniobra hidráulica.', 'ACTIVO'),
  (2, 'COLLARINES-DE-TOMA', 'Collarines de Toma', 'Collarines de derivación simple y reforzada para tuberías de polietileno y PVC.', 'ACTIVO'),
  (3, 'CONEXIONES-HDPE', 'Conexiones HDPE', 'Codos de 90°, tees, enlaces rectos, terminales roscados y adaptadores de compresión en polietileno de alta densidad.', 'ACTIVO'),
  (4, 'ACCESORIOS-ROSCADOS-PP', 'Accesorios Roscados PP', 'Nipples, uniones, bujes de reducción, tapones y codos roscados en polipropileno de alta resistencia.', 'ACTIVO'),
  (5, 'ASPERSORES-Y-MICROASPERSORES', 'Aspersores y Microaspersores', 'Aspersores sectoriales de impacto, microaspersores circulares, estacas, boquillas y accesorios de riego aéreo.', 'ACTIVO'),
  (6, 'ACCESORIOS-PARA-MANGUERA-Y-CINTA', 'Accesorios para Manguera y Cinta', 'Conectores iniciales, enlaces simples, tees dentadas, terminales en ocho y válvulas para cintas de goteo.', 'ACTIVO'),
  (7, 'MANGUERAS', 'Mangueras', 'Mangueras agrícolas de polietileno HDPE, mangueras reforzadas para succión y descarga pesada, mangueras automotrices y flexibles.', 'ACTIVO'),
  (8, 'GOTERO-Y-ACCESORIOS', 'Gotero y Accesorios', 'Goteros autocompensantes, goteros botón desarmables, punzones sacabocados y microtubos de distribución.', 'ACTIVO'),
  (9, 'EMBALAJES', 'Embalajes', 'Sunchos plásticos, grapas metálicas, film stretch de embalaje y herramientas de flejado industrial.', 'ACTIVO'),
  (10, 'OTROS', 'Otros', 'Accesorios complementarios de instalación, teflón industrial, manómetros y herramientas de campo.', 'ACTIVO'),
  (11, 'MALLAS', 'Mallas', 'Mallas Raschel con diversos porcentajes de sombra (35\% a 90\%), mallas mosquiteras y mallas antipájaros para protección de cultivos.', 'ACTIVO');

